// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Collection } from '@stdlib/types/array';

/**
* Data set instance.
*/
interface DataSet {
	/**
	* Serializes an instance to a JSON object.
	*
	* @returns JSON object
	*/
	toJSON(): object;
}

/**
* Converts an array to a "tidy" data set.
*
* @param arr - input array
* @param name - data set name
* @param fields - list of field names
* @returns data set instance
*
* @example
* var x = [ 1, 2, 3 ];
*
* var v = array2tidy( x, 'data', [ 'index', 'value' ] );
* // returns <DataSet>
*/
declare function array2tidy<T = unknown>( arr: Collection<T>, name: string, fields: Array<string> ): DataSet;


// EXPORTS //

export = array2tidy;
